  void dashboard(LinearLayout body){FrameLayout hero=new FrameLayout(this);hero.setBackground(bg(ink,dp(24)));hero.setClipToOutline(true);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,dp(174));hp.bottomMargin=dp(16);body.addView(hero,hp);hero.addView(new HeroArt(this),new FrameLayout.LayoutParams(-1,-1));LinearLayout copy=column();copy.setPadding(dp(20),dp(20),dp(18),dp(16));hero.addView(copy,new FrameLayout.LayoutParams(-1,-1));TextView kicker=text("TODAY'S WORKSPACE",11,0xFFD4EAE5);kicker.setLetterSpacing(.12f);copy.addView(kicker);TextView headline=text("Every case,\none clear next step.",24,Color.WHITE);headline.setTypeface(null,1);LinearLayout.LayoutParams x=new LinearLayout.LayoutParams(-1,-2);x.topMargin=dp(7);copy.addView(headline,x);copy.addView(text("Rajvee · Recovery Desk",13,0xFFE2F2EE));
    Cursor cur=db.getReadableDatabase().rawQuery("SELECT COUNT(*),SUM(CASE WHEN days>0 THEN 1 ELSE 0 END) FROM cases WHERE LOWER(COALESCE(paymentstatus,'Unpaid'))!='paid'",null);cur.moveToFirst();int total=cur.getInt(0),over=cur.isNull(1)?0:cur.getInt(1);cur.close();Cursor pt=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM cases WHERE ptpdate=? AND LOWER(COALESCE(paymentstatus,'Unpaid'))!='paid'",new String[]{today()});pt.moveToFirst();int due=pt.getInt(0);pt.close();LinearLayout metrics=new LinearLayout(this);metrics.setOrientation(0);metrics.addView(metric("OPEN CASES",total,teal),new LinearLayout.LayoutParams(0,dp(84),1));metrics.addView(metric("OVERDUE",over,red),new LinearLayout.LayoutParams(0,dp(84),1));metrics.addView(metric("PTP TODAY",due,ink),new LinearLayout.LayoutParams(0,dp(84),1));body.addView(metrics);body.addView(heading("Your work buckets"));TextView internal=text("Internal agent labels · tap to open the full list",13,Color.DKGRAY);body.addView(internal);HorizontalScrollView hv=new HorizontalScrollView(this);hv.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);row.setOrientation(0);row.setPadding(0,dp(3),0,dp(4));hv.addView(row);for(int i=1;i<=3;i++)bucketTile(row,i);body.addView(hv);body.addView(heading("Today's promises"));showTodayPtps(body);body.addView(heading("Recently updated"));list=column();body.addView(list);render();}
  MaterialCardView metric(String label,int value,int accent){MaterialCardView c=card();c.setStrokeColor(0xFFE9EFEC);LinearLayout box=column();box.setPadding(dp(12),dp(10),dp(8),dp(8));c.addView(box);TextView n=text(""+value,25,accent);n.setTypeface(null,1);box.addView(n);TextView l=text(label,10,Color.DKGRAY);l.setLetterSpacing(.04f);box.addView(l);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(84),1);p.setMargins(dp(2),0,dp(2),0);c.setLayoutParams(p);return c;}
  void bucketTile(LinearLayout row,int emi){Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM cases WHERE emi=? AND LOWER(COALESCE(paymentstatus,'Unpaid'))='unpaid'",new String[]{""+emi});c.moveToFirst();int count=c.getInt(0);c.close();MaterialCardView tile=card();tile.setCardBackgroundColor(emi==1?0xFFE4F2EE:emi==2?0xFFFFF2DC:0xFFFCEAE7);LinearLayout box=column();box.setGravity(Gravity.CENTER_VERTICAL);box.setPadding(dp(15),dp(12),dp(15),dp(12));tile.addView(box);TextView label=text(bucket(emi),18,ink);label.setTypeface(null,1);label.setMaxLines(1);label.setEllipsize(android.text.TextUtils.TruncateAt.END);box.addView(label);TextView countLabel=text(count+" unpaid cases",13,Color.DKGRAY);countLabel.setMaxLines(1);countLabel.setEllipsize(android.text.TextUtils.TruncateAt.END);box.addView(countLabel);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(180),dp(96));p.setMargins(0,0,dp(10),0);row.addView(tile,p);tile.setOnClickListener(v->{bottom.setSelectedItemId(emi+1);showPage("bucket"+emi);});}
  void showTodayPtps(LinearLayout page){String date=today();Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,ptpamount,ptpresult FROM cases WHERE ptpdate=? AND LOWER(COALESCE(paymentstatus,'Unpaid'))!='paid' ORDER BY name",new String[]{date});if(!c.moveToFirst()){MaterialCardView empty=card();TextView t=text("No unpaid promises due today",14,Color.DKGRAY);t.setPadding(dp(15),dp(14),dp(15),dp(14));empty.addView(t);page.addView(empty);c.close();return;}do{long id=c.getLong(0);MaterialCardView item=card();LinearLayout row=column();row.setPadding(dp(15),dp(12),dp(15),dp(11));TextView name=text(c.getString(1),16,ink);name.setTypeface(null,1);row.addView(name);String amount=c.getString(2),result=c.getString(3);row.addView(text("Promised "+(amount==null||amount.isEmpty()?"amount not entered":amount)+"  ·  "+(result==null||result.isEmpty()?"Pending":result),13,teal));item.addView(row);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(7);page.addView(item,p);item.setOnClickListener(v->details(id));}while(c.moveToNext());c.close();}
  String today(){return new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
  class HeroArt extends View {Paint paint=new Paint(3);HeroArt(Context c){super(c);setWillNotDraw(false);}protected void onDraw(Canvas canvas){super.onDraw(canvas);float w=getWidth(),h=getHeight();paint.setShader(new LinearGradient(0,0,w,h,new int[]{0xFF0D3D39,0xFF126B60},null,Shader.TileMode.CLAMP));canvas.drawRect(0,0,w,h,paint);paint.setShader(null);paint.setColor(0x1FFFFFFF);canvas.drawCircle(w*.88f,h*.04f,h*.72f,paint);paint.setColor(0x17CBE4D9);canvas.drawCircle(w*.91f,h*.12f,h*.51f,paint);paint.setColor(0x24FFFFFF);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(1));canvas.drawArc(w*.53f,h*.23f,w*1.12f,h*1.37f,210,210,false,paint);canvas.drawArc(w*.66f,h*.17f,w*1.18f,h*1.44f,35,178,false,paint);paint.setStyle(Paint.Style.FILL);}}
  void render(){
    if(list==null)return;list.removeAllViews();String q=search==null?"":search.getText().toString().toLowerCase(Locale.ROOT);int f=filter==null?0:filter.getSelectedItemPosition();Cursor c=db.getReadableDatabase().rawQuery("SELECT * FROM cases ORDER BY updated DESC",null);int displayed=0;boolean allCases=currentPage.equals("allcases");
    while(c.moveToNext()){
      long id=c.getLong(c.getColumnIndexOrThrow("id"));String name=c.getString(c.getColumnIndexOrThrow("name")),phone=c.getString(c.getColumnIndexOrThrow("phone")),ref=c.getString(c.getColumnIndexOrThrow("ref")),loanNo=c.getString(c.getColumnIndexOrThrow("loanno"));int emi=c.getInt(c.getColumnIndexOrThrow("emi")),days=c.getInt(c.getColumnIndexOrThrow("days"));String ptp=c.getString(c.getColumnIndexOrThrow("ptpdate")),visit=c.getString(c.getColumnIndexOrThrow("visit")),lender=get(id,"lender","");String payment=get(id,"paymentstatus","Unpaid");boolean paid=payment.equalsIgnoreCase("Paid"),rtpStatus=payment.equalsIgnoreCase("RTP");
      if(currentPage.equals("imported")&&!lastOcrIds.contains(id))continue;
      if(currentPage.equals("paid")&&!paid)continue;if(currentPage.equals("rtp")&&!rtpStatus)continue;
      if(!allCases&&!currentPage.equals("paid")&&!currentPage.equals("rtp")&&!currentPage.equals("imported")&&(paid||rtpStatus))continue;
      if(!(name+phone+ref+loanNo+ptp).toLowerCase(Locale.ROOT).contains(q))continue;
      if(currentPage.equals("photos")){list.addView(photoCaseCard(id,name,get(id,"photo","")));displayed++;continue;}
      if(currentPage.startsWith("bucket")&&emi!=num(currentPage.substring(6)))continue;
      if(currentPage.equals("today")&&!today().equals(ptp))continue;if(currentPage.equals("visits")&&visit.equalsIgnoreCase("Completed"))continue;if(currentPage.equals("npa")&&emi!=4)continue;
      if(currentPage.equals("allcases")&&f>0&&emi!=f-1)continue;
      if(currentPage.equals("all")){if(f>=1&&f<=5&&emi!=f-1)continue;if(f==6&&days<=0)continue;if(f==7&&ptp.isEmpty())continue;if(f==8&&visit.equalsIgnoreCase("Completed"))continue;if(f==9&&!visit.equalsIgnoreCase("Completed"))continue;if(f==10&&!dateIs(ptp,0))continue;if(f==11&&!dateIs(ptp,1))continue;if(f==12&&!dateIs(ptp,7))continue;}
      if(currentPage.equals("dashboard")&&displayed>=5)continue;list.addView(caseCard(id,name,phone,ref,loanNo,emi,days,ptp,visit,lender));displayed++;
    }
    c.close();if(displayed==0){MaterialCardView empty=card();String message=currentPage.equals("photos")?"No unpaid cases yet. Add a case to attach a photo.":currentPage.equals("paid")?"No paid cases yet":currentPage.equals("rtp")?"No RTP cases yet":currentPage.equals("imported")?"No imported cases to show":currentPage.equals("allcases")?"No cases in this view":"No unpaid cases in this view";TextView t=text(message,15,Color.DKGRAY);t.setPadding(dp(16),dp(17),dp(16),dp(17));empty.addView(t);list.addView(empty);}
  }
  MaterialCardView photoCaseCard(long id,String name,String path){MaterialCardView item=card();LinearLayout box=column();box.setPadding(dp(14),dp(12),dp(14),dp(12));item.addView(box);TextView title=text(name,17,ink);title.setTypeface(null,1);box.addView(title);if(!path.isEmpty()){File photo=new File(path);if(photo.isFile()){ImageView preview=new ImageView(this);preview.setImageBitmap(decodePreview(photo));preview.setAdjustViewBounds(true);preview.setScaleType(ImageView.ScaleType.CENTER_CROP);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(180));pp.topMargin=dp(8);box.addView(preview,pp);}}box.addView(button(path.isEmpty()?"Add photo":"View / replace photo",()->{if(path.isEmpty())chooseCasePhoto(id);else showPhoto(id);}));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);item.setLayoutParams(lp);return item;}
  MaterialCardView caseCard(long id,String name,String phone,String ref,String loanNo,int emi,int days,String ptp,String visit,String lender){MaterialCardView card=card();LinearLayout body=column();body.setPadding(dp(15),dp(12),dp(15),dp(12));card.addView(body);LinearLayout titleRow=new LinearLayout(this);titleRow.setGravity(Gravity.CENTER_VERTICAL);TextView nm=text(name,18,ink);nm.setTypeface(null,1);titleRow.addView(nm,new LinearLayout.LayoutParams(0,-2,1));TextView bucket=text(bucket(emi),11,teal);bucket.setTypeface(null,1);bucket.setPadding(dp(9),dp(5),dp(9),dp(5));bucket.setBackground(bg(0xFFE2F1ED,dp(12)));titleRow.addView(bucket);body.addView(titleRow);if(!ref.isEmpty())body.addView(text("REF  "+ref,11,Color.GRAY));if(!loanNo.isEmpty())body.addView(text("LOAN  "+loanNo,11,Color.GRAY));LinearLayout details=new LinearLayout(this);details.setPadding(0,dp(5),0,0);details.addView(text(phone.isEmpty()?"Mobile not entered":phone,13,Color.DKGRAY),new LinearLayout.LayoutParams(0,-2,1));TextView over=text(days+" days overdue",12,days>0?red:teal);details.addView(over);body.addView(details);View line=new View(this);line.setBackgroundColor(0xFFE8ECE9);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(1));lp.topMargin=dp(8);lp.bottomMargin=dp(7);body.addView(line,lp);body.addView(text("PTP  "+(ptp.isEmpty()?"Not set":ptp),12,Color.DKGRAY));boolean completed="Completed".equalsIgnoreCase(visit);String visitDate=get(id,"visitdate","");TextView visitStatus=text(completed?"Visit completed"+(visitDate.trim().isEmpty()?"":" ("+visitDate+")"):"Visit not completed",12,completed?Color.rgb(25,126,65):Color.DKGRAY);if(completed){visitStatus.setTypeface(null,1);visitStatus.setCompoundDrawablesRelativeWithIntrinsicBounds(getDrawable(R.drawable.ic_visit_complete),null,null,null);visitStatus.setCompoundDrawablePadding(dp(6));}body.addView(visitStatus);body.addView(text("Payment: "+get(id,"paymentstatus","Unpaid")+"     ·     Lender: "+(lender.isEmpty()?"Not reported":lender),12,teal));card.setOnClickListener(v->details(id));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(9);card.setLayoutParams(p);return card;}
  boolean dateIs(String value,int mode){try{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setLenient(false);Date d=f.parse(value);Calendar day=Calendar.getInstance();day.set(Calendar.HOUR_OF_DAY,0);day.set(Calendar.MINUTE,0);day.set(Calendar.SECOND,0);day.set(Calendar.MILLISECOND,0);long delta=d.getTime()-day.getTimeInMillis();if(mode==0)return delta>=0&&delta<86400000L;if(mode==1)return delta<0;return delta>=0&&delta<=7L*86400000L;}catch(Exception e){return false;}}
  void editBuckets(){LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(20,8,20,8);EditText[] values=new EditText[3];for(int i=1;i<=3;i++){values[i-1]=new EditText(this);values[i-1].setSingleLine(true);values[i-1].setHint("SMA "+(i-1)+" label");values[i-1].setText(bucket(i));form.addView(values[i-1]);}new AlertDialog.Builder(this).setTitle("Internal agent bucket labels").setMessage("These labels are internal and do not set lender status.").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{android.content.SharedPreferences.Editor e=getSharedPreferences("rajvi",MODE_PRIVATE).edit();for(int i=1;i<=3;i++)if(!values[i-1].getText().toString().trim().isEmpty())e.putString("bucket"+i,values[i-1].getText().toString().trim());e.apply();home();}).show();}
  String bucket(int n){if(n==4)return "NPA";if(n<1||n>3)return "Unmapped";return getSharedPreferences("rajvi",MODE_PRIVATE).getString("bucket"+n,n==1?"SMA 0":n==2?"SMA 1":"SMA 2");}String get(long id,String col,String def){Cursor c=db.getReadableDatabase().rawQuery("SELECT "+col+" FROM cases WHERE id=?",new String[]{""+id});String x=def;if(c.moveToFirst()&&!c.isNull(0))x=c.getString(0);c.close();return x;}
  void edit(Long id){
    Cursor c=id==null?null:db.getReadableDatabase().rawQuery("SELECT * FROM cases WHERE id=?",new String[]{""+id});if(c!=null)c.moveToFirst();
    LinearLayout form=column();form.setPadding(dp(18),dp(10),dp(18),dp(12));ScrollView scroll=new ScrollView(this);scroll.addView(form);
    HashMap<String,EditText> fields=new HashMap<>();HashMap<String,String> original=new HashMap<>();Spinner[] ptpResultPick={null};
    String[][] specs={{"name","Borrower name *"},{"loanno","Loan number"},{"phone","Mobile number (10 digits)"},{"visitdate","Visit date"},{"outcome","Visit outcome"},{"ptpamount","PTP promised amount"},{"ptpdate","PTP date"},{"ptpresult","PTP outcome (Pending / Kept / Missed)"},{"notes","Case notes"}};
    for(String[] sp:specs){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);EditText e=new EditText(this);e.setSingleLine(!sp[0].equals("notes")&&!sp[0].equals("outcome"));if(sp[0].equals("phone"))configureMobileNumber(e);e.setHint(sp[1]);e.setTextSize(17);e.setPadding(dp(12),dp(8),dp(12),dp(8));e.setMinHeight(dp(56));e.setBackground(bg(Color.WHITE,dp(12)));if(c!=null){int ix=c.getColumnIndex(sp[0]);if(ix>=0){String value=c.getString(ix);e.setText(value);original.put(sp[0],value==null?"":value);}}if(sp[0].equals("ptpresult")){form.addView(text(sp[1],13,teal));Spinner result=new Spinner(this);String[] results={"Pending","Kept","Missed"};result.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,results));for(int i=0;i<results.length;i++)if(results[i].equalsIgnoreCase(e.getText().toString().trim()))result.setSelection(i);row.addView(result,new LinearLayout.LayoutParams(-1,dp(56)));ptpResultPick[0]=result;}else{LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(0,-2,1);ep.bottomMargin=dp(9);row.addView(e,ep);if(sp[0].equals("oldest")||sp[0].equals("visitdate")||sp[0].equals("ptpdate")){e.setFocusable(false);e.setOnClickListener(v->pickDate(e));MaterialButton cal=new MaterialButton(this);cal.setText("▦");cal.setTextSize(20);cal.setContentDescription("Choose date");cal.setMinWidth(dp(54));cal.setOnClickListener(v->pickDate(e));row.addView(cal,new LinearLayout.LayoutParams(dp(58),dp(56)));}}form.addView(row);fields.put(sp[0],e);}
    int existingEmi=c==null?0:num(c.getString(c.getColumnIndexOrThrow("emi")));String payment=c==null?"Unpaid":c.getString(c.getColumnIndexOrThrow("paymentstatus"));String visit=c==null?"Pending":c.getString(c.getColumnIndexOrThrow("visit"));String existingPaidAmount=c==null?"":get(id,"paidamount","");if(c!=null){original.put("emi",""+existingEmi);original.put("paymentstatus",payment==null?"Unpaid":payment);original.put("paidamount",existingPaidAmount);original.put("visit",visit==null?"Pending":visit);c.close();}
    form.addView(text("CASE CATEGORY",11,teal));Spinner bucketPick=new Spinner(this);String[] bucketOpts={"Unmapped",bucket(1),bucket(2),bucket(3),"NPA"};bucketPick.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,bucketOpts));bucketPick.setSelection(Math.max(0,Math.min(4,existingEmi)));form.addView(bucketPick);
    form.addView(text("PAYMENT STATUS",11,teal));Spinner paymentPick=new Spinner(this);paymentPick.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Unpaid","Paid","RTP"}));paymentPick.setSelection("Paid".equalsIgnoreCase(payment)?1:"RTP".equalsIgnoreCase(payment)?2:0);form.addView(paymentPick);LinearLayout paidAmountRow=column();EditText paidAmountField=new EditText(this);paidAmountField.setSingleLine(true);paidAmountField.setTextSize(17);paidAmountField.setHint("Paid amount (optional)");paidAmountField.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);paidAmountField.setPadding(dp(12),dp(8),dp(12),dp(8));paidAmountField.setMinHeight(dp(56));paidAmountField.setBackground(bg(Color.WHITE,dp(12)));paidAmountField.setText(existingPaidAmount);paidAmountRow.addView(paidAmountField,new LinearLayout.LayoutParams(-1,-2));paidAmountRow.setVisibility("Paid".equalsIgnoreCase(payment)?View.VISIBLE:View.GONE);form.addView(paidAmountRow);paymentPick.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?> a,View v,int position,long rowId){paidAmountRow.setVisibility(position==1?View.VISIBLE:View.GONE);}});
    form.addView(text("VISIT STATUS",11,teal));Spinner visitPick=new Spinner(this);visitPick.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Pending","Completed"}));visitPick.setSelection("Completed".equalsIgnoreCase(visit)?1:0);form.addView(visitPick);
    Spinner voiceField=new Spinner(this);String[] voiceFields={"Case notes","Borrower name","Mobile number","Visit outcome","PTP amount","PTP date"};voiceField.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,voiceFields));form.addView(voiceField);Button voice=button("🎙 Dictate selected field",()->{String[] keys={"notes","name","phone","outcome","ptpamount","ptpdate"};dictationTarget=fields.get(keys[voiceField.getSelectedItemPosition()]);Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_PROMPT,"Review the recognized text before saving");try{startActivityForResult(i,VOICE);}catch(Exception ex){toast("Speech recognition is unavailable on this device");}});form.addView(voice);
    AlertDialog dialog=new AlertDialog.Builder(this).setTitle(id==null?"Add borrower case":"Edit borrower case").setView(scroll).setNegativeButton(batchMode?"Finish batch":"Cancel",(a,b)->{batchMode=false;home();}).setPositiveButton(batchMode?"Save + next":"Save case",null).create();
    dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{String borrower=fields.get("name").getText().toString().trim();if(borrower.isEmpty()){fields.get("name").setError("Required");return;}String similar=id==null?findSimilarBorrowerName(borrower):"";if(!similar.isEmpty()){new AlertDialog.Builder(this).setTitle("Possible duplicate borrower").setMessage("A similar borrower name already exists: "+similar+". Save this as another case?").setNegativeButton("Cancel",null).setPositiveButton("Save anyway",(a,b)->saveCaseForm(id,dialog,fields,original,bucketPick,paymentPick,paidAmountField,visitPick,ptpResultPick)).show();return;}saveCaseForm(id,dialog,fields,original,bucketPick,paymentPick,paidAmountField,visitPick,ptpResultPick);}));dialog.show();
  }
  void saveCaseForm(Long id,AlertDialog dialog,HashMap<String,EditText> fields,HashMap<String,String> original,Spinner bucketPick,Spinner paymentPick,EditText paidAmountField,Spinner visitPick,Spinner[] ptpResultPick){fields.get("ptpresult").setText(ptpResultPick[0].getSelectedItem().toString());ContentValues cv=new ContentValues();String[][] specs={{"name",""},{"loanno",""},{"phone",""},{"visitdate",""},{"outcome",""},{"ptpamount",""},{"ptpdate",""},{"ptpresult",""},{"notes",""}};for(String[] sp:specs)cv.put(sp[0],fields.get(sp[0]).getText().toString());cv.put("emi",bucketPick.getSelectedItemPosition());String savedPayment=paymentPick.getSelectedItem().toString();cv.put("paymentstatus",savedPayment);cv.put("paidamount","Paid".equalsIgnoreCase(savedPayment)?paidAmountField.getText().toString().trim():"");cv.put("visit",visitPick.getSelectedItem().toString());if(id==null){cv.put("ref","");cv.put("amount","");cv.put("oldest","");cv.put("days",0);}cv.put("updated",System.currentTimeMillis());long saved;if(id==null)saved=db.getWritableDatabase().insert("cases",null,cv);else{db.getWritableDatabase().update("cases",cv,"id=?",new String[]{""+id});saved=id;}if(id==null){db.history(saved,"Case created");if(!fields.get("ptpamount").getText().toString().trim().isEmpty()||!fields.get("ptpdate").getText().toString().trim().isEmpty()||!fields.get("ptpresult").getText().toString().trim().isEmpty())db.history(saved,ptpEvent(fields.get("ptpamount").getText().toString(),fields.get("ptpdate").getText().toString(),fields.get("ptpresult").getText().toString()));}else{boolean notesChanged=!original.getOrDefault("notes","").equals(fields.get("notes").getText().toString());boolean visitChanged=!original.getOrDefault("visit","Pending").equals(visitPick.getSelectedItem().toString())||!original.getOrDefault("visitdate","").equals(fields.get("visitdate").getText().toString())||!original.getOrDefault("outcome","").equals(fields.get("outcome").getText().toString());boolean ptpChanged=!original.getOrDefault("ptpamount","").equals(fields.get("ptpamount").getText().toString())||!original.getOrDefault("ptpdate","").equals(fields.get("ptpdate").getText().toString())||!original.getOrDefault("ptpresult","").equals(fields.get("ptpresult").getText().toString());boolean emiChanged=num(original.getOrDefault("emi","0"))!=bucketPick.getSelectedItemPosition();boolean paidChanged=!original.getOrDefault("paymentstatus","Unpaid").equals(paymentPick.getSelectedItem().toString());boolean paidAmountChanged=!original.getOrDefault("paidamount","").equals(paidAmountField.getText().toString().trim());if(notesChanged)db.history(saved,"Case notes updated");if(visitChanged)db.history(saved,"Visit details updated");if(ptpChanged)db.history(saved,ptpEvent(fields.get("ptpamount").getText().toString(),fields.get("ptpdate").getText().toString(),fields.get("ptpresult").getText().toString()));if(emiChanged)db.history(saved,"Case category changed");if(paidChanged)db.history(saved,"Payment status changed");if(paidAmountChanged)db.history(saved,"Paid amount updated");if(!notesChanged&&!visitChanged&&!ptpChanged&&!emiChanged&&!paidChanged&&!paidAmountChanged)db.history(saved,"Case details updated");}dialog.dismiss();if(batchMode)edit(null);else home();}
  String findSimilarBorrowerName(String name){String key=borrowerNameKey(name);if(key.isEmpty())return "";Cursor c=db.getReadableDatabase().rawQuery("SELECT name FROM cases",null);String found="";while(c.moveToNext()){String existing=c.getString(0);if(nameSimilarity(key,borrowerNameKey(existing))>=0.82){found=existing;break;}}c.close();return found;}
  double nameSimilarity(String a,String b){if(a.isEmpty()||b.isEmpty())return 0;if(a.equals(b))return 1;String[] aa=a.split(" "),bb=b.split(" ");HashSet<String> tokens=new HashSet<>(Arrays.asList(aa));int shared=0;for(String token:bb)if(tokens.contains(token))shared++;double tokenScore=(double)shared/Math.max(aa.length,bb.length);int[][] d=new int[a.length()+1][b.length()+1];for(int i=0;i<=a.length();i++)d[i][0]=i;for(int j=0;j<=b.length();j++)d[0][j]=j;for(int i=1;i<=a.length();i++)for(int j=1;j<=b.length();j++)d[i][j]=Math.min(Math.min(d[i-1][j]+1,d[i][j-1]+1),d[i-1][j-1]+(a.charAt(i-1)==b.charAt(j-1)?0:1));double editScore=1.0-(double)d[a.length()][b.length()]/Math.max(a.length(),b.length());return Math.max(tokenScore,editScore);}
  void pickDate(EditText target){Calendar cal=Calendar.getInstance();try{String[] d=target.getText().toString().split("-");if(d.length==3){cal.set(Integer.parseInt(d[0]),Integer.parseInt(d[1])-1,Integer.parseInt(d[2]));}}catch(Exception ignored){}new DatePickerDialog(this,(v,y,m,day)->target.setText(String.format(Locale.US,"%04d-%02d-%02d",y,m+1,day)),cal.get(Calendar.YEAR),cal.get(Calendar.MONTH),cal.get(Calendar.DAY_OF_MONTH)).show();}
  String ptpEvent(String amount,String date,String result){return "PTP updated · Amount: "+(amount.trim().isEmpty()?"not set":amount.trim())+" · Date: "+(date.trim().isEmpty()?"not set":date.trim())+" · Outcome: "+(result.trim().isEmpty()?"Pending":result.trim());}
  int num(String s){try{return Integer.parseInt(s.trim());}catch(Exception e){return 0;}}
  void details(long id){String name=get(id,"name","Case");String phone=get(id,"phone","");String payment=get(id,"paymentstatus","Unpaid");String paidAmount=get(id,"paidamount","");boolean paid="Paid".equalsIgnoreCase(payment);boolean hasPtp=!get(id,"ptpamount","").trim().isEmpty()||!get(id,"ptpdate","").trim().isEmpty();final AlertDialog[] detailDialog={null};LinearLayout actions=column();actions.setPadding(dp(18),dp(10),dp(18),dp(12));TextView paymentStatus=text("Payment status: "+(paid?"Paid":"Unpaid"),14,paid?Color.rgb(25,126,65):teal);paymentStatus.setTypeface(null,1);paymentStatus.setPadding(dp(12),dp(9),dp(12),dp(9));paymentStatus.setBackground(bg(paid?0xFFE7F4EA:0xFFE3F3EE,dp(14)));actions.addView(paymentStatus);if(paid&&!paidAmount.trim().isEmpty())actions.addView(text("Paid amount: "+paidAmount,14,teal));actions.addView(space(8));actions.addView(button("Change payment status",()->{if(detailDialog[0]!=null)detailDialog[0].dismiss();showPaymentEditor(id);}));actions.addView(space(8));Button call=button("Call borrower",()->{Intent callIntent=new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+Uri.encode(phone)));startActivity(callIntent);db.history(id,"Opened phone dialer");});call.setEnabled(!phone.trim().isEmpty());actions.addView(call);actions.addView(space(8));actions.addView(button(hasPtp?"Update PTP amount / date":"New PTP amount / date",()->showPtpEditor(id)));actions.addView(space(8));actions.addView(button("Update visit status",()->showVisitEditor(id)));actions.addView(space(8));actions.addView(button("View case history",()->history(id)));MaterialButton editFull=new MaterialButton(this);editFull.setText("Edit full case details");editFull.setTextSize(13);editFull.setAllCaps(false);editFull.setTextColor(teal);editFull.setMinHeight(dp(42));editFull.setCornerRadius(dp(12));editFull.setStrokeWidth(dp(1));editFull.setStrokeColor(android.content.res.ColorStateList.valueOf(0xFFB8D3CD));editFull.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.WHITE));editFull.setOnClickListener(v->edit(id));actions.addView(space(4));actions.addView(editFull);detailDialog[0]=new AlertDialog.Builder(this).setTitle(name).setView(actions).setNegativeButton("Close",null).create();detailDialog[0].show();}
  void showPaymentEditor(long id){String oldStatus=get(id,"paymentstatus","Unpaid"),oldAmount=get(id,"paidamount","");LinearLayout form=column();form.setPadding(dp(18),dp(8),dp(18),dp(10));Spinner status=new Spinner(this);String[] statuses={"Unpaid","Paid","RTP"};status.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,statuses));status.setSelection("Paid".equalsIgnoreCase(oldStatus)?1:"RTP".equalsIgnoreCase(oldStatus)?2:0);form.addView(status);EditText amount=new EditText(this);amount.setSingleLine(true);amount.setHint("Paid amount (optional)");amount.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);amount.setText(oldAmount);form.addView(amount);amount.setVisibility("Paid".equalsIgnoreCase(oldStatus)?View.VISIBLE:View.GONE);status.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?> a,View v,int position,long rowId){amount.setVisibility(position==1?View.VISIBLE:View.GONE);}});AlertDialog editor=new AlertDialog.Builder(this).setTitle("Change payment status").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();editor.setOnShowListener(v->editor.getButton(-1).setOnClickListener(w->{String nextStatus=status.getSelectedItem().toString(),nextAmount="Paid".equals(nextStatus)?amount.getText().toString().trim():"";ContentValues values=new ContentValues();values.put("paymentstatus",nextStatus);values.put("paidamount",nextAmount);values.put("updated",System.currentTimeMillis());db.getWritableDatabase().update("cases",values,"id=?",new String[]{""+id});if(!oldStatus.equalsIgnoreCase(nextStatus))db.history(id,"Payment status changed to "+nextStatus);if(!oldAmount.equals(nextAmount)&&!nextAmount.isEmpty())db.history(id,"Paid amount updated");editor.dismiss();home();}));editor.show();}
  void showPtpEditor(long id){LinearLayout form=column();form.setPadding(dp(18),dp(8),dp(18),dp(10));EditText amount=new EditText(this);amount.setSingleLine(true);amount.setHint("PTP amount");amount.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);amount.setText(get(id,"ptpamount",""));form.addView(amount);EditText date=new EditText(this);date.setSingleLine(true);date.setHint("PTP date");date.setFocusable(false);date.setText(get(id,"ptpdate",""));date.setOnClickListener(v->pickDate(date));form.addView(date);Spinner outcome=new Spinner(this);String[] results={"Pending","Kept","Missed"};outcome.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,results));String saved=get(id,"ptpresult","Pending");int selected=0;for(int i=0;i<results.length;i++)if(results[i].equalsIgnoreCase(saved))selected=i;outcome.setSelection(selected);form.addView(outcome);new AlertDialog.Builder(this).setTitle("PTP amount and date").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String nextAmount=amount.getText().toString().trim(),nextDate=date.getText().toString().trim(),nextResult=outcome.getSelectedItem().toString();ContentValues values=new ContentValues();values.put("ptpamount",nextAmount);values.put("ptpdate",nextDate);values.put("ptpresult",nextResult);values.put("updated",System.currentTimeMillis());db.getWritableDatabase().update("cases",values,"id=?",new String[]{""+id});db.history(id,ptpEvent(nextAmount,nextDate,nextResult));home();}).show();}
  void showVisitEditor(long id){LinearLayout form=column();form.setPadding(dp(18),dp(8),dp(18),dp(10));Spinner status=new Spinner(this);String[] statuses={"Not completed","✓ Completed"};status.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,statuses));status.setSelection("Completed".equalsIgnoreCase(get(id,"visit","Pending"))?1:0);form.addView(status);EditText date=new EditText(this);date.setSingleLine(true);date.setHint("Visit date");date.setFocusable(false);date.setText(get(id,"visitdate",""));date.setOnClickListener(v->pickDate(date));form.addView(date);EditText outcome=new EditText(this);outcome.setHint("Visit outcome");outcome.setText(get(id,"outcome",""));form.addView(outcome);new AlertDialog.Builder(this).setTitle("Was the visit completed?").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{boolean completed=status.getSelectedItemPosition()==1;String nextStatus=completed?"Completed":"Pending",nextDate=date.getText().toString().trim(),nextOutcome=outcome.getText().toString().trim();ContentValues values=new ContentValues();values.put("visit",nextStatus);values.put("visitdate",nextDate);values.put("outcome",nextOutcome);values.put("updated",System.currentTimeMillis());db.getWritableDatabase().update("cases",values,"id=?",new String[]{""+id});db.history(id,"Visit updated · Status: "+(completed?"Completed":"Not completed")+" · Date: "+(nextDate.isEmpty()?"not set":nextDate)+" · Outcome: "+(nextOutcome.isEmpty()?"not set":nextOutcome));home();}).show();}
  void history(long id){Cursor c=db.getReadableDatabase().rawQuery("SELECT event,at FROM history WHERE caseid=? ORDER BY at DESC",new String[]{""+id});StringBuilder s=new StringBuilder();while(c.moveToNext())s.append(new Date(c.getLong(1))).append("\n").append(c.getString(0)).append("\n\n");c.close();new AlertDialog.Builder(this).setTitle("Case history").setMessage(s.length()==0?"No history yet":s.toString()).setPositiveButton("Done",null).show();}
  void templates(){String[] templates={"Payment reminder","PTP follow-up","Visit scheduling"};new AlertDialog.Builder(this).setTitle("Message templates · manual only").setItems(templates,(d,n)->template(templates[n])).setNegativeButton("Done",null).show();}
  void template(String title){EditText e=new EditText(this);e.setMinLines(5);e.setText("Hello {borrower}, this is your recovery agent. Please contact us regarding your account and pending payment. Reply with a convenient time to discuss.");new AlertDialog.Builder(this).setTitle(title+" (edit before use)").setView(e).setNeutralButton("Copy",(d,w)->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText(title,e.getText()));toast("Copied. Send manually when ready.");}).setPositiveButton("Share…",(d,w)->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,e.getText().toString());startActivity(Intent.createChooser(i,"Share message manually"));}).setNegativeButton("Close",null).show();}
  void batchOptions(){new AlertDialog.Builder(this).setTitle("Add multiple records").setItems(new String[]{"Enter cases manually","Import Excel workbook","Read PDF or photo (OCR + review)"},(d,n)->{if(n==0){batchMode=true;edit(null);}else if(n==1)chooseBatchFile(true);else chooseBatchFile(false);}).show();}
  void chooseBatchFile(boolean excel){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);if(excel){i.setType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");}else{i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","image/*"});i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);}try{startActivityForResult(i,IMPORT_FILE);}catch(Exception e){toast("File picker is unavailable");}}
  void pickCaseDocument(long id){mediaCaseId=id;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"});try{startActivityForResult(i,CASE_DOCUMENT);}catch(Exception e){toast("File picker is unavailable");}}
  void chooseCasePhoto(long id){mediaCaseId=id;new AlertDialog.Builder(this).setTitle("Add a case photo").setItems(new String[]{"Choose from device","Take a photo"},(d,n)->{try{if(n==0){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");startActivityForResult(i,PHOTO);}else{Intent i=new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE);launchCamera(i);startActivityForResult(i,CAMERA);}}catch(Exception e){toast("Photo picker or camera is unavailable");}}).setNegativeButton("Cancel",null).show();}
  Bitmap decodePreview(File file){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getAbsolutePath(),bounds);int sample=1;while(bounds.outWidth/sample>1200||bounds.outHeight/sample>1200)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;return BitmapFactory.decodeFile(file.getAbsolutePath(),options);}
  void showPhoto(long id){String path=get(id,"photo","");File file=new File(path);if(!file.isFile()){toast("The saved photo could not be found");return;}ImageView image=new ImageView(this);image.setImageBitmap(decodePreview(file));image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setMaxHeight(dp(520));new AlertDialog.Builder(this).setTitle(get(id,"name","Case")+" · photo").setView(image).setPositiveButton("Done",null).setNeutralButton("Replace",(d,w)->chooseCasePhoto(id)).show();}
  String fileName(Uri uri){try(Cursor c=getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst()){int i=c.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);if(i>=0)return c.getString(i);}}catch(Exception ignored){}return "imported-file";}
  void handleRecordImport(Uri uri){String name=fileName(uri),lower=name.toLowerCase(Locale.ROOT),mime=getContentResolver().getType(uri);try{if(lower.endsWith(".xlsx")||(mime!=null&&mime.contains("spreadsheetml"))){int n=importWorkbook(uri);toast("Imported "+n+" case records from Excel");home();}else if(lower.endsWith(".json")||(mime!=null&&mime.contains("json"))){BufferedReader r=new BufferedReader(new InputStreamReader(getContentResolver().openInputStream(uri)));StringBuilder b=new StringBuilder();String line;while((line=r.readLine())!=null)b.append(line);r.close();db.importJson(b.toString());toast("JSON records imported");home();}else if(lower.endsWith(".pdf")||(mime!=null&&mime.equals("application/pdf"))){runOcr(uri,true,name);}else if(mime!=null&&mime.startsWith("image/")){runOcr(uri,false,name);}else toast("Choose an .xlsx, JSON, PDF, or image file");}catch(Exception e){toast("Could not import this file");}}
  void chooseAttachmentCase(Uri uri,boolean photo){Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,phone FROM cases ORDER BY name",null);ArrayList<Long> ids=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();while(c.moveToNext()){ids.add(c.getLong(0));labels.add(c.getString(1)+"  ·  "+c.getString(2));}c.close();if(ids.isEmpty()){toast("Add a case before attaching a file");return;}new AlertDialog.Builder(this).setTitle("Attach to which case?").setItems(labels.toArray(new String[0]),(d,n)->{mediaCaseId=ids.get(n);if(photo)attachPhoto(uri,null);else attachDocument(uri);}).setNegativeButton("Cancel",null).show();}
  void attachDocument(Uri uri){try{String source=fileName(uri);File dir=new File(getFilesDir(),"case-media");dir.mkdirs();String safe=source.replaceAll("[^A-Za-z0-9._-]","_");File f=new File(dir,"case-"+mediaCaseId+"-"+System.currentTimeMillis()+"-"+safe);InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(f);byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);in.close();out.close();ContentValues v=new ContentValues();v.put("docpath",f.getAbsolutePath());v.put("docname",source);db.getWritableDatabase().update("cases",v,"id=?",new String[]{""+mediaCaseId});db.history(mediaCaseId,"Document attached: "+source);toast("Document attached to case");home();}catch(Exception e){toast("Could not attach document");}}
  void handleMultipleOcrImport(ArrayList<Uri> uris){ArrayList<OcrSource> sources=new ArrayList<>();int skipped=0;for(Uri uri:uris){String name=fileName(uri),lower=name.toLowerCase(Locale.ROOT),mime=getContentResolver().getType(uri);boolean pdf=lower.endsWith(".pdf")||(mime!=null&&mime.equalsIgnoreCase("application/pdf"));boolean image=(mime!=null&&mime.startsWith("image/"))||lower.matches(".*\\.(jpg|jpeg|png|webp|bmp|heic)$");if(pdf||image){try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}sources.add(new OcrSource(uri,pdf,name));}else skipped++;}if(sources.isEmpty()){toast("Select photo or PDF files for OCR");return;}if(skipped>0)toast("Some selected files were skipped");runOcr(sources);}
  void runOcr(Uri uri,boolean pdf,String name){ArrayList<OcrSource> sources=new ArrayList<>();sources.add(new OcrSource(uri,pdf,name));runOcr(sources);}
  void runOcr(ArrayList<OcrSource> sources){
    ProgressDialog progress=new ProgressDialog(this);progress.setMessage("Reading selected photos on this device…");progress.setCancelable(false);progress.show();
    new Thread(()->{
      ArrayList<OcrRecord> records=new ArrayList<>();int failures=0;com.google.mlkit.vision.text.TextRecognizer recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);
      try{for(OcrSource source:sources){File temp=null;try{if(source.pdf){temp=File.createTempFile("rajvi-ocr-",".pdf",getCacheDir());try(InputStream in=getContentResolver().openInputStream(source.uri);OutputStream out=new FileOutputStream(temp)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(temp,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd)){int pageCount=renderer.getPageCount();for(int p=0;p<pageCount;p++){PdfRenderer.Page page=renderer.openPage(p);Bitmap bitmap=null;try{float scale=Math.min(2f,1800f/page.getWidth());bitmap=Bitmap.createBitmap(Math.max(1,(int)(page.getWidth()*scale)),Math.max(1,(int)(page.getHeight()*scale)),Bitmap.Config.ARGB_8888);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);com.google.mlkit.vision.text.Text result=Tasks.await(recognizer.process(InputImage.fromBitmap(bitmap,0)));addOcrPageRecords(records,source,p+1,result);}finally{if(bitmap!=null)bitmap.recycle();page.close();}}}}else{InputImage image=InputImage.fromFilePath(this,source.uri);com.google.mlkit.vision.text.Text result=Tasks.await(recognizer.process(image));addOcrPageRecords(records,source,1,result);}}catch(Exception ex){failures++;}finally{if(temp!=null)temp.delete();}}}finally{recognizer.close();}
      int failedCount=failures;runOnUiThread(()->{progress.dismiss();if(records.isEmpty()){toast("Could not read the selected photos. Try clearer images or PDFs.");return;}if(failedCount>0)toast("Some selected files could not be read");saveOcrRecords(new OcrImportSession(sources,records));});
    }).start();
  }
  void addOcrPageRecords(ArrayList<OcrRecord> records,OcrSource source,int page,com.google.mlkit.vision.text.Text result){String recognized=result==null?"":result.getText();if(recognized.trim().isEmpty())return;ArrayList<String> visualRows=ocrVisualRows(result);ArrayList<String> rows=new ArrayList<>();for(String line:visualRows){String candidate=line.trim();if(!candidate.isEmpty()&&!extractBorrowerName(candidate).isEmpty())rows.add(candidate);}if(rows.size()>1){for(String row:rows)records.add(new OcrRecord(source,page,row));}else records.add(new OcrRecord(source,page,recognized));}
  ArrayList<String> ocrVisualRows(com.google.mlkit.vision.text.Text result){ArrayList<com.google.mlkit.vision.text.Text.Line> lines=new ArrayList<>();for(com.google.mlkit.vision.text.Text.TextBlock block:result.getTextBlocks())lines.addAll(block.getLines());if(lines.isEmpty())return new ArrayList<>();Collections.sort(lines,(a,b)->Integer.compare(a.getBoundingBox()==null?0:a.getBoundingBox().centerY(),b.getBoundingBox()==null?0:b.getBoundingBox().centerY()));ArrayList<String> rows=new ArrayList<>();ArrayList<com.google.mlkit.vision.text.Text.Line> group=new ArrayList<>();int center=0;for(com.google.mlkit.vision.text.Text.Line line:lines){android.graphics.Rect box=line.getBoundingBox();int y=box==null?center:box.centerY();int tolerance=box==null?12:Math.max(10,box.height()/2);if(!group.isEmpty()&&Math.abs(y-center)>tolerance){rows.add(joinOcrLineGroup(group));group.clear();}group.add(line);int total=0;for(com.google.mlkit.vision.text.Text.Line item:group){android.graphics.Rect r=item.getBoundingBox();total+=r==null?y:r.centerY();}center=total/group.size();}if(!group.isEmpty())rows.add(joinOcrLineGroup(group));return rows;}
  String joinOcrLineGroup(ArrayList<com.google.mlkit.vision.text.Text.Line> group){Collections.sort(group,(a,b)->Integer.compare(a.getBoundingBox()==null?0:a.getBoundingBox().left,b.getBoundingBox()==null?0:b.getBoundingBox().left));StringBuilder row=new StringBuilder();for(com.google.mlkit.vision.text.Text.Line line:group){if(row.length()>0)row.append(' ');row.append(line.getText());}return row.toString();}
  HashMap<String,String> extractOcr(String raw){HashMap<String,String> m=new HashMap<>();m.put("ref",match(raw,"(?im)^(?:reference|ref|account\\s*(?:no|number))\\s*[:#-]\\s*(.+)$"));String loanNo=match(raw,"(?im)^(?:loan\\s*(?:no|number)|loan\\s*account(?:\\s*(?:no|number))?)\\s*[:#-]\\s*(.+)$");if(loanNo.isEmpty())loanNo=extractNonMobileIdentifier(raw);m.put("loanno",loanNo);m.put("name",extractBorrowerName(raw));m.put("phone",extractMobile(raw));String emi=match(raw,"(?im)(?:overdue|pending|unpaid)\\s*(?:emi|installments?)?\\D{0,12}([0-3])\\s*(?:emi|installments?)|([0-3])\\s*(?:emi|installments?)\\s*(?:overdue|pending|unpaid)");if(emi.isEmpty())emi="";else{java.util.regex.Matcher em=java.util.regex.Pattern.compile("[0-3]").matcher(emi);if(em.find())emi=em.group();}String smaBucket=match(raw,"(?i)\\bSMA\\s*[- ]?([0-2])\\b");if(!smaBucket.isEmpty())emi=""+(num(smaBucket)+1);else if(java.util.regex.Pattern.compile("(?i)\\bNPA\\b").matcher(raw).find())emi="4";m.put("emi",emi);m.put("amount",match(raw,"(?im)(?:overdue\\s*amount|amount\\s*due|total\\s*due)\\s*[:#-]?\\s*(?:₹|rs\\.?\\s*)?([0-9,]+(?:\\.[0-9]{1,2})?)"));m.put("oldest",normalizeDate(match(raw,"(?im)(?:oldest\\s*due|due\\s*date)\\s*[:#-]?\\s*([0-9]{1,4}[./-][0-9]{1,2}[./-][0-9]{1,4})")));m.put("days",match(raw,"(?im)(?:days?\\s*overdue|dpd)\\s*[:#-]?\\s*([0-9]{1,4})"));String lender=match(raw,"(?im)(?:lender\\s*reported\\s*)?(SMA\\s*[0-2]|NPA)\\b");m.put("lender",lender);m.put("visit",match(raw,"(?im)visit\\s*status\\s*[:#-]?\\s*(pending|completed|done)"));m.put("visitdate",normalizeDate(match(raw,"(?im)visit\\s*date\\s*[:#-]?\\s*([0-9]{1,4}[./-][0-9]{1,2}[./-][0-9]{1,4})")));m.put("outcome",match(raw,"(?im)visit\\s*outcome\\s*[:#-]?\\s*(.+)$"));m.put("ptpamount",match(raw,"(?im)PTP\\s*(?:amount)?\\s*[:#-]?\\s*(?:₹|rs\\.?\\s*)?([0-9,]+(?:\\.[0-9]{1,2})?)"));String ptpDate=normalizeDate(match(raw,"(?im)PTP\\s*date\\s*[:#-]?\\s*([0-9]{1,4}[./-][0-9]{1,2}[./-][0-9]{1,4})"));if(ptpDate.isEmpty())ptpDate=currentMonthDate(match(raw,"(?is)PTP.{0,120}?(?:\\bRF\\s*[-/]?\\s*(\\d{1,2})\\b|\\b(\\d{1,2})\\s*RF\\b)"));m.put("ptpdate",ptpDate);m.put("ptpresult",match(raw,"(?im)PTP\\s*(?:outcome|status)\\s*[:#-]?\\s*(pending|kept|missed|paid)"));m.put("paymentstatus",match(raw,"(?im)payment\\s*status\\s*[:#-]?\\s*(paid|unpaid|rtp)"));return m;}
  String extractBorrowerName(String raw){String value=extractNameWithLabel(raw);if(value.isEmpty())value=match(raw,"(?im)\\b(?:mr|mrs|ms|miss|shri|sri)\\.?\\s+([A-Za-z][A-Za-z'.-]*(?:[ ,;]+[A-Za-z][A-Za-z'.-]*){1,12}?)(?=\\s+(?:SMA\\s*[- ]?[0-2]|NPA|STAB|CONFIRM|UNPAID|PAID)\\b|\\s*[|\\t;]|$)");if(value.isEmpty())value=match(raw,"(?im)^\\s*(?:mr|mrs|ms|miss|shri|sri)\\.?\\s+([A-Za-z][A-Za-z'.-]*(?:[ ,;]+[A-Za-z][A-Za-z'.-]*){1,12})$");String name=normalizeBorrowerName(value);return name.split("\\s+").length>=2?name:"";}
  String normalizeBorrowerName(String name){if(name==null||name.trim().isEmpty())return "";String clean=name.trim().replaceFirst("(?i)\\s*[,;]?\\s+(?:mr|mrs|ms|miss|shri|sri)\\.?\\s+.*$","").replaceFirst("(?i)^(?:mr|mrs|ms|miss|shri|sri)\\.?\\s+","");return clean.replaceAll("\\s+"," ").replaceAll("[,;]+$","").trim();}
  String extractNameWithLabel(String raw){String[] lines=raw.split("\\r?\\n");java.util.regex.Pattern label=java.util.regex.Pattern.compile("^\\s*(?:(?:borrower|customer|cust)\\.?\\s*names?)\\s*[:#-]?\\s*(.*)$",java.util.regex.Pattern.CASE_INSENSITIVE);for(int i=0;i<lines.length;i++){java.util.regex.Matcher matcher=label.matcher(lines[i]);if(!matcher.matches())continue;StringBuilder name=new StringBuilder(matcher.group(1).trim());for(int j=i+1;j<lines.length&&normalizeBorrowerName(name.toString()).split("\\s+").length<3;j++){String next=lines[j].trim();if(name.length()>0&&next.matches("(?i)^(?:mr|mrs|ms|miss|shri|sri)\\.?\\s+.*"))break;if(!isNameContinuation(next))break;if(name.length()>0)name.append(' ');name.append(next);}return name.toString().trim();}return "";}
  boolean isNameContinuation(String value){if(value==null||value.trim().isEmpty()||value.contains(":"))return false;if(value.matches("(?i)^(mobile|phone|contact|loan|account|ref|reference|address|ptp|visit|amount|lender|status|date|emi|payment|outcome|cust|customer|borrower)\\b.*"))return false;if(value.matches("(?i)^(?:mr|mrs|ms|miss|shri|sri)\\.?\\s+[A-Za-z][A-Za-z'.-]*(?:[ ,;]+[A-Za-z][A-Za-z'.-]*){1,20}$"))return true;return value.matches("[A-Za-z][A-Za-z'.-]*(?:\\s+[A-Za-z][A-Za-z'.-]*){0,3}");}
  String extractNonMobileIdentifier(String raw){String value=match(raw,"(?im)^(?:mobile|phone|contact)(?:\\s*(?:no|number))?\\s*[:#-]?\\s*([A-Za-z0-9+()][A-Za-z0-9+() ._/-]*)$");if(value.isEmpty())return "";String digits=value.replaceAll("[^0-9]","");if(value.matches("[0-9+() .-]+")&&digits.length()==10)return "";return value.trim();}
  String extractMobile(String raw){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?im)^(?:mobile|phone|contact)(?:\\s*(?:no|number))?\\s*[:#-]?\\s*([0-9+() .-]+)$").matcher(raw);if(!m.find())return "";String digits=m.group(1).replaceAll("[^0-9]","");return digits.length()==10?digits:"";}
  String match(String raw,String pattern){java.util.regex.Matcher m=java.util.regex.Pattern.compile(pattern).matcher(raw);if(!m.find())return "";for(int i=1;i<=m.groupCount();i++)if(m.group(i)!=null)return m.group(i).trim();return "";}
  String normalizeDate(String value){if(value==null||value.isEmpty())return "";String[] p=value.split("[./-]");try{if(p.length!=3)return value;int y,mo,d;if(p[0].length()==4){y=Integer.parseInt(p[0]);mo=Integer.parseInt(p[1]);d=Integer.parseInt(p[2]);}else{d=Integer.parseInt(p[0]);mo=Integer.parseInt(p[1]);y=Integer.parseInt(p[2]);if(y<100)y+=2000;}if(y<2000||mo<1||mo>12||d<1||d>31)return value;return String.format(Locale.US,"%04d-%02d-%02d",y,mo,d);}catch(Exception e){return value;}}
  String currentMonthDate(String day){try{int d=Integer.parseInt(day);Calendar c=Calendar.getInstance();if(d<1||d>c.getActualMaximum(Calendar.DAY_OF_MONTH))return "";c.set(Calendar.DAY_OF_MONTH,d);return new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(c.getTime());}catch(Exception e){return "";}}
  class OcrSource {final Uri uri;final boolean pdf;final String name;File sourceCopy;OcrSource(Uri uri,boolean pdf,String name){this.uri=uri;this.pdf=pdf;this.name=name;}}
  class OcrImportSession {final ArrayList<OcrSource> sources;final ArrayList<OcrRecord> records;OcrImportSession(ArrayList<OcrSource> sources,ArrayList<OcrRecord> records){this.sources=sources;this.records=records;}}
  class OcrRecord {final OcrSource source;final int page;final String recognized;final HashMap<String,String> fields;OcrRecord(OcrSource source,int page,String recognized){this.source=source;this.page=page;this.recognized=recognized;fields=extractOcr(recognized);}}
  String borrowerNameKey(String name){return normalizeBorrowerName(name).toLowerCase(java.util.Locale.ROOT).replaceAll("[^a-z0-9]+"," ").trim().replaceAll("\\s+"," ");}
  boolean ocrDuplicate(HashMap<String,String> candidate,ArrayList<String[]> existing){String name=borrowerNameKey(candidate.getOrDefault("name",""));String phone=candidate.getOrDefault("phone","").replaceAll("\\D","");String loan=borrowerNameKey(candidate.getOrDefault("loanno",""));String ref=borrowerNameKey(candidate.getOrDefault("ref",""));for(String[] row:existing){String oldName=row[0],oldPhone=row[1],oldLoan=row[2],oldRef=row[3];if(!loan.isEmpty()&&loan.equals(oldLoan))return true;if(!ref.isEmpty()&&ref.equals(oldRef))return true;if(!phone.isEmpty()&&phone.equals(oldPhone))return true;if(!name.isEmpty()&&name.equals(oldName)&&(phone.isEmpty()||oldPhone.isEmpty()||phone.equals(oldPhone)))return true;}return false;}
  void saveOcrRecords(OcrImportSession session){ArrayList<OcrRecord> valid=new ArrayList<>();int skippedNames=0,skippedDuplicates=0;ArrayList<String[]> known=new ArrayList<>();try(Cursor cursor=db.getReadableDatabase().rawQuery("SELECT name,phone,loanno,ref FROM cases",null)){while(cursor.moveToNext())known.add(new String[]{borrowerNameKey(cursor.getString(0)),cursor.getString(1)==null?"":cursor.getString(1).replaceAll("\\D",""),borrowerNameKey(cursor.getString(2)),borrowerNameKey(cursor.getString(3))});}for(OcrRecord record:session.records){HashMap<String,String> fields=record.fields;String name=fields.getOrDefault("name","").trim();if(name.isEmpty()){skippedNames++;continue;}if(ocrDuplicate(fields,known)){skippedDuplicates++;continue;}valid.add(record);known.add(new String[]{borrowerNameKey(name),fields.getOrDefault("phone","").replaceAll("\\D",""),borrowerNameKey(fields.getOrDefault("loanno","")),borrowerNameKey(fields.getOrDefault("ref",""))});}if(valid.isEmpty()){toast(skippedDuplicates>0?"No new OCR cases: duplicates were skipped":"No borrower names found in the selected file");return;}ArrayList<Long> savedIds=new ArrayList<>();SQLiteDatabase writable=db.getWritableDatabase();writable.beginTransaction();try{for(OcrRecord record:valid){ContentValues values=new ContentValues();String[] keys={"ref","loanno","name","phone","amount","oldest","lender","visit","visitdate","outcome","ptpamount","ptpdate","ptpresult"};for(String key:keys)values.put(key,record.fields.getOrDefault(key,"").trim());values.put("paymentstatus","Unpaid");values.put("paidamount","");values.put("emi",num(record.fields.getOrDefault("emi","")));values.put("days",num(record.fields.getOrDefault("days","")));values.put("notes","");values.put("updated",System.currentTimeMillis());long id=writable.insert("cases",null,values);if(id<0)throw new SQLiteException("Case insert failed");savedIds.add(id);db.history(id,"Created from OCR · "+record.source.name+" · page "+record.page);attachOcrSource(record,id);}writable.setTransactionSuccessful();}catch(Exception e){toast("Could not save OCR records");return;}finally{writable.endTransaction();}lastOcrIds.clear();lastOcrIds.addAll(savedIds);home();showPage("imported");toast("Added "+savedIds.size()+" OCR records"+(skippedDuplicates>0?" · skipped "+skippedDuplicates+" duplicate records":"")+(skippedNames>0?" · skipped "+skippedNames+" without a readable borrower name":""));}
  File attachOcrSource(OcrRecord record,long id){OcrSource source=record.source;try{if(source.sourceCopy==null||!source.sourceCopy.isFile()){File dir=new File(getFilesDir(),"case-media");dir.mkdirs();String safe=source.name.replaceAll("[^A-Za-z0-9._-]","_");source.sourceCopy=new File(dir,"ocr-"+System.currentTimeMillis()+"-"+safe);try(InputStream in=getContentResolver().openInputStream(source.uri);OutputStream out=new FileOutputStream(source.sourceCopy)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}}ContentValues values=new ContentValues();if(source.pdf){values.put("docpath",source.sourceCopy.getAbsolutePath());values.put("docname",source.name);}else{values.put("photo",source.sourceCopy.getAbsolutePath());values.put("photocaption","Imported via OCR");}db.getWritableDatabase().update("cases",values,"id=?",new String[]{""+id});db.history(id,source.pdf?"Source PDF attached":"Source photo attached");}catch(Exception e){toast("Case added, but source file could not be attached");}return source.sourceCopy;}
  int importWorkbook(Uri uri)throws Exception{
    String sheetXml=null,sharedXml=null;try(ZipInputStream zip=new ZipInputStream(getContentResolver().openInputStream(uri))){ZipEntry e;while((e=zip.getNextEntry())!=null){if(e.getName().equals("xl/worksheets/sheet1.xml")||e.getName().equals("xl/sharedStrings.xml")){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=zip.read(buf))>0)b.write(buf,0,n);if(e.getName().equals("xl/worksheets/sheet1.xml"))sheetXml=new String(b.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);else sharedXml=new String(b.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}}}
    if(sheetXml==null)throw new IOException("Workbook sheet missing");javax.xml.parsers.DocumentBuilderFactory f=javax.xml.parsers.DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);ArrayList<String> shared=new ArrayList<>();if(sharedXml!=null){org.w3c.dom.Document sd=f.newDocumentBuilder().parse(new java.io.ByteArrayInputStream(sharedXml.getBytes(java.nio.charset.StandardCharsets.UTF_8)));org.w3c.dom.NodeList sis=sd.getElementsByTagName("si");for(int i=0;i<sis.getLength();i++)shared.add(sis.item(i).getTextContent());}
    org.w3c.dom.Document doc=f.newDocumentBuilder().parse(new java.io.ByteArrayInputStream(sheetXml.getBytes(java.nio.charset.StandardCharsets.UTF_8)));org.w3c.dom.NodeList rows=doc.getElementsByTagName("row");if(rows.getLength()<2)return 0;ArrayList<String> headers=workbookRow((org.w3c.dom.Element)rows.item(0),shared);int imported=0;
    for(int r=1;r<rows.getLength();r++){ArrayList<String> cells=workbookRow((org.w3c.dom.Element)rows.item(r),shared);HashMap<String,String> m=new HashMap<>();for(int j=0;j<headers.size()&&j<cells.size();j++)m.put(headers.get(j),cells.get(j));String borrower=m.getOrDefault("Borrower name","").trim();if(borrower.isEmpty())continue;ContentValues v=new ContentValues();v.put("ref",m.getOrDefault("Internal reference",""));v.put("loanno",m.getOrDefault("Loan number",""));v.put("name",borrower);v.put("phone",m.getOrDefault("Mobile number",""));v.put("emi",num(m.getOrDefault("Overdue EMI count","0")));v.put("amount",m.getOrDefault("Overdue amount",""));v.put("oldest",m.getOrDefault("Oldest due date",""));v.put("days",num(m.getOrDefault("Days overdue","0")));v.put("lender",m.getOrDefault("Lender-reported status",""));v.put("visit",m.getOrDefault("Visit status","Pending"));v.put("visitdate",m.getOrDefault("Visit date",""));v.put("outcome",m.getOrDefault("Visit outcome",""));v.put("ptpamount",m.getOrDefault("PTP amount",""));v.put("ptpdate",m.getOrDefault("PTP date",""));v.put("ptpresult",m.getOrDefault("PTP outcome","Pending"));v.put("notes",m.getOrDefault("Notes",""));v.put("paymentstatus",m.getOrDefault("Payment status","Unpaid"));v.put("paidamount",m.getOrDefault("Paid amount",""));v.put("updated",System.currentTimeMillis());long id=db.getWritableDatabase().insert("cases",null,v);db.history(id,"Imported from Excel workbook");imported++;}return imported;
  }
  ArrayList<String> workbookRow(org.w3c.dom.Element row,ArrayList<String> shared){ArrayList<String> cells=new ArrayList<>();org.w3c.dom.NodeList nodes=row.getElementsByTagName("c");for(int i=0;i<nodes.getLength();i++){org.w3c.dom.Element cell=(org.w3c.dom.Element)nodes.item(i);org.w3c.dom.NodeList values=cell.getElementsByTagName("v");String value="";if("s".equals(cell.getAttribute("t"))&&values.getLength()>0){try{value=shared.get(Integer.parseInt(values.item(0).getTextContent()));}catch(Exception ignored){}}else{org.w3c.dom.NodeList t=cell.getElementsByTagName("t");if(t.getLength()>0)value=t.item(0).getTextContent();else if(values.getLength()>0)value=values.item(0).getTextContent();}int index=columnNumber(cell.getAttribute("r"))-1;while(cells.size()<=index&&index>=0)cells.add("");if(index>=0)cells.set(index,value);}return cells;}
  int columnNumber(String ref){int n=0;for(int i=0;i<ref.length()&&Character.isLetter(ref.charAt(i));i++)n=n*26+(Character.toUpperCase(ref.charAt(i))-'A'+1);return n;}
  void backup(){String[] opts={"Export JSON backup","Import JSON backup"};new AlertDialog.Builder(this).setTitle("Offline backup").setItems(opts,(d,n)->{if(n==0){String out=db.exportJson();Intent i=new Intent(Intent.ACTION_SEND);i.setType("application/json");i.putExtra(Intent.EXTRA_TEXT,out);startActivity(Intent.createChooser(i,"Share JSON backup"));}else{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}}).show();}
  void confirmClearRecords(){AlertDialog confirm=new AlertDialog.Builder(this).setTitle("Clear all records?").setMessage("This permanently deletes all borrower cases, their history, and saved case media. Exported backup files are not deleted.").setNegativeButton("Cancel",null).setPositiveButton("Clear all",(d,w)->clearAllRecords()).create();confirm.setOnShowListener(v->confirm.getButton(-1).setTextColor(red));confirm.show();}
  void clearAllRecords(){try{SQLiteDatabase writable=db.getWritableDatabase();writable.beginTransaction();try{writable.delete("history",null,null);writable.delete("cases",null,null);writable.setTransactionSuccessful();}finally{writable.endTransaction();}boolean mediaRemoved=clearDirectory(new File(getFilesDir(),"case-media"));home();toast(mediaRemoved?"All borrower records and history cleared":"Records cleared, but some saved media could not be deleted");}catch(Exception e){toast("Could not clear the records");}}
  boolean clearDirectory(File directory){if(!directory.exists())return true;File[] children=directory.listFiles();if(children==null)return false;boolean success=true;for(File child:children){if(child.isDirectory()&&!clearDirectory(child))success=false;if(!child.delete())success=false;}return success;}
  void exportRecords(){new AlertDialog.Builder(this).setTitle("Export case records").setItems(new String[]{"PDF report","Excel workbook (.xlsx)"},(d,n)->exportAction(n==0)).show();}
  void exportAction(boolean pdf){if(pdf){new AlertDialog.Builder(this).setTitle("Choose PDF cases").setItems(new String[]{"All cases · Paid, Unpaid and RTP","Paid cases only","Unpaid cases only","RTP cases only"},(d,n)->{pdfExportFilter=n;getSharedPreferences("rajvi",MODE_PRIVATE).edit().putInt("pendingPdfFilter",n).apply();exportDestination(true);}).show();}else exportDestination(false);}
  String pdfExportFileName(){return pdfExportFilter==1?"rajvi-paid-records.pdf":pdfExportFilter==2?"rajvi-unpaid-records.pdf":pdfExportFilter==3?"rajvi-rtp-records.pdf":"rajvi-records.pdf";}
  void exportDestination(boolean pdf){new AlertDialog.Builder(this).setTitle(pdf?"PDF report":"Excel workbook").setItems(new String[]{"Save to device…","Share…"},(d,n)->{if(n==0){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(pdf?"application/pdf":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");i.putExtra(Intent.EXTRA_TITLE,pdf?pdfExportFileName():"rajvi-records.xlsx");try{startActivityForResult(i,pdf?EXPORT_PDF:EXPORT_XLSX);}catch(Exception e){toast("The save picker is unavailable");}}else shareRecords(pdf);}).show();}
  ArrayList<String[]> recordRows(){ArrayList<String[]> rows=new ArrayList<>();rows.add(new String[]{"Internal reference","Loan number","Borrower name","Mobile number","Overdue EMI count","Overdue amount","Oldest due date","Days overdue","Internal agent bucket","Payment status","Paid amount","Lender-reported status","Visit status","Visit date","Visit outcome","PTP amount","PTP date","PTP outcome","Notes","Last updated","Photo attached","Document attached"});Cursor c=db.getReadableDatabase().rawQuery("SELECT * FROM cases ORDER BY name",null);while(c.moveToNext()){int emi=c.getInt(c.getColumnIndexOrThrow("emi"));long updated=c.getLong(c.getColumnIndexOrThrow("updated"));rows.add(new String[]{val(c,"ref"),val(c,"loanno"),val(c,"name"),val(c,"phone"),""+emi,val(c,"amount"),val(c,"oldest"),val(c,"days"),bucket(emi),val(c,"paymentstatus"),val(c,"paidamount"),val(c,"lender"),val(c,"visit"),val(c,"visitdate"),val(c,"outcome"),val(c,"ptpamount"),val(c,"ptpdate"),val(c,"ptpresult"),val(c,"notes"),updated==0?"":new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(new Date(updated)),val(c,"photo").isEmpty()?"No":"Yes",val(c,"docpath").isEmpty()?"No":"Yes"});}c.close();return rows;}
  String val(Cursor c,String column){int i=c.getColumnIndex(column);return i<0||c.isNull(i)?"":c.getString(i);}
  void shareRecords(boolean pdf){try{File dir=new File(getFilesDir(),"exports");dir.mkdirs();File f=new File(dir,pdf?pdfExportFileName():"rajvi-records.xlsx");try(OutputStream out=new FileOutputStream(f)){if(pdf)writePdf(out,pdfExportFilter);else writeXlsx(out);}Uri uri=Uri.parse("content://com.rajvee.recoverydesk.media/exports/"+f.getName());Intent i=new Intent(Intent.ACTION_SEND);i.setType(pdf?"application/pdf":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");i.putExtra(Intent.EXTRA_STREAM,uri);i.setClipData(ClipData.newUri(getContentResolver(),f.getName(),uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Share case records"));}catch(Exception e){toast("Could not prepare export file");}}
  void saveRecords(Uri uri,boolean pdf){try(OutputStream out=getContentResolver().openOutputStream(uri)){if(pdf)writePdf(out,pdfExportFilter);else writeXlsx(out);toast("Export saved");}catch(Exception e){toast("Could not save export");}}
  void writePdf(OutputStream out,int exportFilter)throws IOException{
    ArrayList<String[]> paid=new ArrayList<>(),unpaid=new ArrayList<>(),rtp=new ArrayList<>();int[] smaCounts={0,0,0};
    Cursor rows=db.getReadableDatabase().rawQuery("SELECT name,paymentstatus,emi FROM cases ORDER BY name COLLATE NOCASE",null);
    while(rows.moveToNext()){int emi=rows.getInt(rows.getColumnIndexOrThrow("emi"));String[] record={val(rows,"name"),Integer.toString(emi)};String status=val(rows,"paymentstatus").trim();ArrayList<String[]> target=null;if("Paid".equalsIgnoreCase(status)){if(exportFilter==0||exportFilter==1)target=paid;}else if("RTP".equalsIgnoreCase(status)){if(exportFilter==0||exportFilter==3)target=rtp;}else if(exportFilter==0||exportFilter==2)target=unpaid;if(target!=null){target.add(record);if(emi>=1&&emi<=3)smaCounts[emi-1]++;}}rows.close();
    PdfDocument doc=new PdfDocument();Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);int pageNo=1;
    PdfDocument.Page page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,pageNo).create());Canvas canvas=page.getCanvas();int y=pdfExportHeader(canvas,paint,paid.size(),unpaid.size(),rtp.size(),smaCounts,true);
    ArrayList<ArrayList<String[]>> groups=new ArrayList<>();ArrayList<String> namesList=new ArrayList<>();if(exportFilter==0||exportFilter==1){groups.add(paid);namesList.add("Paid");}if(exportFilter==0||exportFilter==2){groups.add(unpaid);namesList.add("Unpaid");}if(exportFilter==0||exportFilter==3){groups.add(rtp);namesList.add("RTP");}String[] names=namesList.toArray(new String[0]);
    for(int group=0;group<groups.size();group++){
      ArrayList<String[]> records=groups.get(group);String statusTitle=names[group]+" cases ("+records.size()+")";
      if(y+55>790){doc.finishPage(page);page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageNo).create());canvas=page.getCanvas();y=pdfExportHeader(canvas,paint,paid.size(),unpaid.size(),rtp.size(),smaCounts,false);}
      y=pdfExportSection(canvas,paint,statusTitle,y);
      for(int sma=1;sma<=3;sma++){
        ArrayList<String[]> bucketRecords=new ArrayList<>();for(String[] record:records)if(Integer.toString(sma).equals(record[1]))bucketRecords.add(record);
        if(y+55>790){doc.finishPage(page);page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageNo).create());canvas=page.getCanvas();y=pdfExportHeader(canvas,paint,paid.size(),unpaid.size(),rtp.size(),smaCounts,false);y=pdfExportSection(canvas,paint,statusTitle+" (continued)",y);}
        String smaTitle="SMA "+(sma-1)+" ("+bucketRecords.size()+")";y=pdfExportSection(canvas,paint,smaTitle,y);
        if(bucketRecords.isEmpty()){paint.setColor(0xFF56635F);paint.setTextSize(11);canvas.drawText("No cases",42,y+4,paint);y+=22;continue;}
        y=pdfExportColumns(canvas,paint,y);
        for(String[] record:bucketRecords){if(y+26>800){doc.finishPage(page);page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageNo).create());canvas=page.getCanvas();y=pdfExportHeader(canvas,paint,paid.size(),unpaid.size(),rtp.size(),smaCounts,false);y=pdfExportSection(canvas,paint,statusTitle+" (continued)",y);y=pdfExportSection(canvas,paint,smaTitle+" (continued)",y);y=pdfExportColumns(canvas,paint,y);}y=pdfExportRow(canvas,paint,record,y);}
        y+=10;
      }
      y+=8;
    }
    doc.finishPage(page);doc.writeTo(out);doc.close();
  }
  int pdfExportHeader(Canvas canvas,Paint paint,int paid,int unpaid,int rtp,int[] smaCounts,boolean first){paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));paint.setColor(0xFF176B62);paint.setTextSize(18);canvas.drawText("RECOVERY DESK",40,42,paint);paint.setColor(0xFF12302F);paint.setTextSize(15);canvas.drawText("Borrower names",40,66,paint);if(first){paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));paint.setTextSize(11);paint.setColor(0xFF263532);canvas.drawText("Paid: "+paid+"   ·   Unpaid: "+unpaid+"   ·   RTP: "+rtp,40,89,paint);canvas.drawText("SMA 0: "+smaCounts[0]+"   ·   SMA 1: "+smaCounts[1]+"   ·   SMA 2: "+smaCounts[2],40,106,paint);canvas.drawLine(40,118,555,118,paint);return 132;}paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));paint.setTextSize(10);paint.setColor(0xFF6B7773);canvas.drawText("Continued",40,88,paint);canvas.drawLine(40,101,555,101,paint);return 116;}
  int pdfExportSection(Canvas canvas,Paint paint,String title,int y){paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));paint.setTextSize(13);paint.setColor(0xFF12302F);canvas.drawText(title,40,y+5,paint);return y+20;}
  int pdfExportColumns(Canvas canvas,Paint paint,int y){paint.setColor(0xFFE8F1EE);canvas.drawRect(40,y-13,555,y+8,paint);paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));paint.setTextSize(10);paint.setColor(0xFF176B62);canvas.drawText("Borrower name",44,y+2,paint);return y+21;}
  int pdfExportRow(Canvas canvas,Paint paint,String[] record,int y){paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));paint.setTextSize(10);paint.setColor(0xFF263532);canvas.drawText(pdfFit(record[0],paint,500),44,y+2,paint);paint.setColor(0xFFE5EBE8);canvas.drawLine(40,y+9,555,y+9,paint);return y+23;}
  String pdfFit(String value,Paint paint,float maxWidth){if(value==null||value.isEmpty())return "—";String result=value;while(result.length()>1&&paint.measureText(result)>maxWidth)result=result.substring(0,result.length()-1);if(!result.equals(value)&&result.length()>1)result=result.substring(0,result.length()-1)+"…";return result;}
  void writeXlsx(OutputStream output)throws IOException {
    ZipOutputStream z=new ZipOutputStream(output);
    zip(z,"[Content_Types].xml","<?xml version='1.0' encoding='UTF-8'?><Types xmlns='http://schemas.openxmlformats.org/package/2006/content-types'><Default Extension='rels' ContentType='application/vnd.openxmlformats-package.relationships+xml'/><Default Extension='xml' ContentType='application/xml'/><Override PartName='/xl/workbook.xml' ContentType='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml'/><Override PartName='/xl/worksheets/sheet1.xml' ContentType='application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml'/></Types>");
    zip(z,"_rels/.rels","<?xml version='1.0' encoding='UTF-8'?><Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument' Target='xl/workbook.xml'/></Relationships>");
    zip(z,"xl/workbook.xml","<?xml version='1.0' encoding='UTF-8'?><workbook xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='Case records' sheetId='1' r:id='rId1'/></sheets></workbook>");
    zip(z,"xl/_rels/workbook.xml.rels","<?xml version='1.0' encoding='UTF-8'?><Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet' Target='worksheets/sheet1.xml'/></Relationships>");
    StringBuilder sheet=new StringBuilder("<?xml version='1.0' encoding='UTF-8'?><worksheet xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><sheetData>");ArrayList<String[]> rows=recordRows();
    for(int r=0;r<rows.size();r++){sheet.append("<row r='").append(r+1).append("'>");for(int c=0;c<rows.get(r).length;c++){sheet.append("<c r='").append(colName(c+1)).append(r+1).append("' t='inlineStr'><is><t xml:space='preserve'>").append(xml(rows.get(r)[c])).append("</t></is></c>");}sheet.append("</row>");}
    sheet.append("</sheetData></worksheet>");zip(z,"xl/worksheets/sheet1.xml",sheet.toString());z.finish();z.flush();
  }
  String colName(int n){String s="";while(n>0){int r=(n-1)%26;s=(char)('A'+r)+s;n=(n-1)/26;}return s;}
  String xml(String s){StringBuilder b=new StringBuilder();for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c=='&')b.append("&amp;");else if(c=='<')b.append("&lt;");else if(c=='>')b.append("&gt;");else if(c=='\"')b.append("&quot;");else if(c>=32||c=='\n'||c=='\r'||c=='\t')b.append(c);}return b.toString();}
  void zip(ZipOutputStream z,String name,String data)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(data.getBytes(java.nio.charset.StandardCharsets.UTF_8));z.closeEntry();}
  protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK)return;if(r==CAMERA){if(cameraFile!=null&&cameraFile.exists()&&cameraFile.length()>0)attachPhoto(Uri.fromFile(cameraFile),null);else toast("Camera did not return a photo");return;}if(data==null)return;if(r==VOICE&&dictationTarget!=null){ArrayList<String> a=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a!=null&&!a.isEmpty())dictationTarget.append((dictationTarget.length()>0?" ":"")+a.get(0));}if(r==PHOTO){try{getContentResolver().takePersistableUriPermission(data.getData(),Intent.FLAG_GRANT_READ_URI_PERMISSION);attachPhoto(data.getData(),null);}catch(Exception ex){try{attachPhoto(data.getData(),null);}catch(Exception ignored){toast("Could not attach this picture");}}}if(r==EXPORT_PDF||r==EXPORT_XLSX){if(r==EXPORT_PDF)pdfExportFilter=getSharedPreferences("rajvi",MODE_PRIVATE).getInt("pendingPdfFilter",0);saveRecords(data.getData(),r==EXPORT_PDF);return;}if(r==CASE_DOCUMENT){attachDocument(data.getData());return;}if(r==IMPORT_FILE){android.content.ClipData selected=data.getClipData();if(selected!=null&&selected.getItemCount()>1){ArrayList<Uri> uris=new ArrayList<>();for(int i=0;i<selected.getItemCount();i++)uris.add(selected.getItemAt(i).getUri());handleMultipleOcrImport(uris);}else if(data.getData()!=null)handleRecordImport(data.getData());return;}if(r==IMPORT){try{BufferedReader br=new BufferedReader(new InputStreamReader(getContentResolver().openInputStream(data.getData())));StringBuilder s=new StringBuilder();String line;while((line=br.readLine())!=null)s.append(line);db.importJson(s.toString());toast("Backup imported");home();}catch(Exception e){toast("Could not import this backup");}}}
  void launchCamera(Intent intent){try{File dir=new File(getFilesDir(),"camera");dir.mkdirs();cameraFile=new File(dir,"capture-"+System.currentTimeMillis()+".jpg");Uri output=Uri.parse("content://com.rajvee.recoverydesk.media/"+cameraFile.getName());intent.putExtra(android.provider.MediaStore.EXTRA_OUTPUT,output);intent.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newUri(getContentResolver(),"photo",output));}catch(Exception e){throw new RuntimeException(e);}}
  void attachPhoto(Uri uri,Bitmap bitmap){try{File dir=new File(getFilesDir(),"case-media");dir.mkdirs();File file=new File(dir,"case-"+mediaCaseId+"-"+System.currentTimeMillis()+".jpg");if(bitmap!=null){FileOutputStream o=new FileOutputStream(file);bitmap.compress(Bitmap.CompressFormat.JPEG,88,o);o.close();}else{InputStream in="file".equals(uri.getScheme())?new FileInputStream(uri.getPath()):getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(file);byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);in.close();out.close();}ImageView preview=new ImageView(this);Bitmap bm=BitmapFactory.decodeFile(file.getAbsolutePath());preview.setImageBitmap(bm);preview.setAdjustViewBounds(true);EditText cap=new EditText(this);cap.setHint("Optional photo caption");new AlertDialog.Builder(this).setTitle("Preview photo").setView(new LinearLayout(this){{setOrientation(1);setPadding(18,8,18,8);addView(preview);addView(cap);}}).setNegativeButton("Cancel",null).setPositiveButton("Attach",(d,w)->{ContentValues cv=new ContentValues();cv.put("photo",file.getAbsolutePath());cv.put("photocaption",cap.getText().toString());db.getWritableDatabase().update("cases",cv,"id=?",new String[]{""+mediaCaseId});db.history(mediaCaseId,"Photo attached");toast("Photo attached to case");home();}).show();}catch(Exception e){toast("Could not save photo");}}
  void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
  class DB extends SQLiteOpenHelper {DB(Context c){super(c,"rajvi.db",null,7);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE cases(id INTEGER PRIMARY KEY AUTOINCREMENT,ref TEXT,loanno TEXT,name TEXT,phone TEXT,emi INTEGER,amount TEXT,oldest TEXT,days INTEGER,lender TEXT,visit TEXT,visitdate TEXT,outcome TEXT,ptpamount TEXT,ptpdate TEXT,ptpresult TEXT,notes TEXT,photo TEXT,photocaption TEXT,voicepath TEXT,paymentstatus TEXT DEFAULT 'Unpaid',paidamount TEXT,docpath TEXT,docname TEXT,updated INTEGER)");d.execSQL("CREATE TABLE history(id INTEGER PRIMARY KEY AUTOINCREMENT,caseid INTEGER,event TEXT,at INTEGER)");d.execSQL("CREATE TABLE templates(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,body TEXT)");}public void onUpgrade(SQLiteDatabase d,int a,int b){if(a<2){d.execSQL("ALTER TABLE cases ADD COLUMN photocaption TEXT DEFAULT ''");d.execSQL("ALTER TABLE cases ADD COLUMN voicepath TEXT DEFAULT ''");}if(a<3){d.execSQL("ALTER TABLE cases ADD COLUMN paymentstatus TEXT DEFAULT 'Unpaid'");}if(a<4){d.execSQL("ALTER TABLE cases ADD COLUMN docpath TEXT");d.execSQL("ALTER TABLE cases ADD COLUMN docname TEXT");}if(a<5){d.execSQL("ALTER TABLE cases ADD COLUMN paidamount TEXT");}if(a<6){d.execSQL("ALTER TABLE cases ADD COLUMN loanno TEXT");}if(a<7){d.execSQL("UPDATE cases SET emi=4 WHERE UPPER(COALESCE(lender,'')) LIKE '%NPA%'");}}void history(long id,String e){ContentValues v=new ContentValues();v.put("caseid",id);v.put("event",e);v.put("at",System.currentTimeMillis());getWritableDatabase().insert("history",null,v);}
    String exportJson(){JSONArray rows=new JSONArray();Cursor c=getReadableDatabase().rawQuery("SELECT * FROM cases",null);while(c.moveToNext()){JSONObject o=new JSONObject();try{for(int i=1;i<c.getColumnCount();i++)o.put(c.getColumnName(i),c.getString(i));rows.put(o);}catch(Exception ignored){}}c.close();JSONObject wrap=new JSONObject();try{wrap.put("format","rajvee-backup-v1");wrap.put("cases",rows);}catch(Exception ignored){}return wrap.toString();}
    void importJson(String s)throws Exception{JSONArray a=new JSONObject(s).getJSONArray("cases");SQLiteDatabase w=getWritableDatabase();for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);ContentValues v=new ContentValues();String[] cols={"ref","loanno","name","phone","emi","amount","oldest","days","lender","visit","visitdate","outcome","ptpamount","ptpdate","ptpresult","notes","photo","photocaption","voicepath","paymentstatus","paidamount","docpath","docname","updated"};for(String col:cols)if(o.has(col)){if(col.equals("emi")||col.equals("days")||col.equals("updated"))v.put(col,o.optLong(col));else v.put(col,o.optString(col));}w.insert("cases",null,v);}}
  }
